def main():
    n = int(input())
    M = 10**9 + 7
    def mul(A, B):
        return [[sum(A[i][k] * B[k][j] for k in range(2)) % M for j in range(2)] for i in range(2)]
    R = [[1, 0], [0, 1]]; A = [[1, 1], [1, 0]]
    while n:
        if n & 1: R = mul(R, A)
        A = mul(A, A); n >>= 1
    print((R[1][0] * 1 + R[1][1] * 2) % M)

